export const articleContent: Record<string, ContentBlock[]> = {
  "vi-har-alltid-visst-at-vi-ville-bli-foreldre-sammen": [
    { type: "subheading", text: "Pride 2026 · Pasienthistorie." },
    { type: "subheading", text: "Slik ble vi tre: møt familien Bjørkvoll Rydeng." },
    { type: "bold-intro", text: "Maria Kathinca og Julie Bjørkvoll Rydeng visste tidlig at de ville ha barn sammen. Det de ikke visste, var at partnerdonasjon ville gi dem akkurat det de hadde drømt om. Etter tre forsøk og én spontanabort ble Emmy født vinteren 2026. Dette er historien deres." },
    { type: "heading", text: "En liten sorg – og et nytt håp" },
    { type: "paragraph", text: "Da Maria og Julie møttes for ni år siden, visste de raskt at de ville tilbringe livet sammen. Men jo mer forelsket de ble, jo tydeligere ble en tanke de ikke hadde hatt ord for før:" },
    { type: "quote", text: "– Det var nesten en liten sorg å tenke at vi aldri skulle kunne få et barn som var halvt meg og halvt Maria. Jo mer forelsket vi ble, jo sterkere kom det instinktet frem – lysten til å formere seg. Og vi visste ikke engang at partnerdonasjon var en mulighet, sier Julie." },
    { type: "paragraph", text: "Partnerdonasjon innebærer at begge partnerne bidrar biologisk: én gir egg, den andre bærer frem barnet. Det var ikke noe de hadde planlagt å finne ut av den dagen, men gjennom jobben møtte Julie et likekjønnet par som hadde gjort nettopp dette på Island." },
    { type: "quote", text: "– Vi fikk skikkelig blod på tann. Vi følte at dette var det rette for oss å gjøre. Da klarer vi å lage et barn sammen – det nærmeste vi kommer et barn som er halvt mitt og halvt Julie, sier Maria." },
    { type: "paragraph", text: "Da norsk lov åpnet for partnerdonasjon uten medisinsk begrunnelse, var beslutningen tatt. Planene om å reise til utlandet ble lagt bort. De skulle gjøre det hjemme i Oslo." },
    { type: "paragraph", text: "Det var også spørsmål de måtte stille seg: Hvem skulle gå gravid? Hvordan ville det føles å bære frem et egg som biologisk tilhørte den andre? Ville tilknytningen bli den samme?" },
    { type: "quote", text: "– Det var masse spørsmål vi ikke hadde svar på. Det er så individuelt. Men vi var aldri i tvil om at dette var det vi ville, sier Maria." },
    { type: "heading", text: "Å bli sett, ikke bare behandlet" },
    { type: "paragraph", text: "Paret startet prosessen hos en annen klinikk, men opplevde at de ikke ble godt nok fulgt opp og at kjemien ikke stemte. Derfor valgte de å bytte klinikk og fortsette prosessen hos CMedical." },
    { type: "quote", text: "– Vi har møtt på holdninger som mener partnerdonasjon er å tukle med biologien. Hos CMedical ble vi tatt imot med åpne armer og åpent sinn, og følte oss helt hjemme, sier Julie." },
    { type: "paragraph", text: "For Maria hadde dette en ekstra dimensjon. Hun er selv et barn til ved hjelp av donor – fra en tid da anonyme donorer var normen, og da barn ikke hadde lovfestet rett til å vite sin biologiske bakgrunn. Det å ikke vite i mange år hvor man kommer fra, har vært en del av hennes egen historie, og hun har i voksen alder drevet en forening for andre i samme situasjon." },
    { type: "quote", text: "– Jeg har levd dette livet selv. Derfor var det viktig for oss å velge en donor som var lik oss rent personlighetsmessig, men også Skandinavisk, for å gjøre det enklere for Emmy om hun en dag ønsker å ta kontakt. Og vi har kjøpt opp nok strå til at eventuelle søsken har samme donor – fordi vi ønsker å gi alle våre barn samme forutsetning, om de en dag vil ta kontakt med donoren sin." },
    { type: "paragraph", text: "Hos CMedical ble de fulgt opp av sykepleier Jeanette Follestad og lege og gynekolog Birgitte Mitlid-Mork. Begge ble raskt viktige støttepersoner i prosessen." },
    { type: "quote", text: "– Det å bli behandlet av noen som skjønner det, som møter deg med respekt og forståelse på lik linje med alle andre – det har alt å si. Jeanette og Birgitte har vært fantastiske. Vi ble så godt tatt vare på, sier Maria." },
    { type: "paragraph", text: "Utredningen viste at begge lå likt an. Valget om hvem som skulle gå gravid først falt naturlig på Julie siden Maria hadde nylig startet i ny jobb, og følte det var litt dårlig timing å gå ut i permisjon. Derfor ble Maria sine egg hentet ut, og i samråd med behandlende lege og sykepleier ble donor-karakteristika valgt fra en europeisk sædbank." },
    { type: "heading", text: "Sorgen, usikkerheten – og det tredje forsøket" },
    { type: "paragraph", text: "Første forsøk var i desember 2024. Julie ble gravid – på aller første forsøk." },
    { type: "quote", text: "– Vi var helt i skyene. Det var helt fantastisk. Jeg levde på en rosa sky, sier Maria." },
    { type: "paragraph", text: "Men i uke 7 begynte det å blø. De kontaktet Birgitte, som holdt åpent på slutten av en fredag slik at paret skulle slippe å gå inn i helgen uten svar. Der fikk de bekreftet det de fryktet: en spontanabort." },
    { type: "quote", text: "– Vi gikk hjem og sørget på sofaen. Det var tøft. Men vi gav hverandre tid, og så prøvde vi igjen, sier Julie." },
    { type: "paragraph", text: "Andre forsøk i mars 2025 festet seg ikke. Begge kjente på at det begynte å bli tungt – fysisk og følelsesmessig." },
    { type: "quote", text: "– Man kjenner veldig på at man ikke har kontroll. Du er vant til å ha kontroll på så mange områder i livet, og så er det bare kroppen som bestemmer. Det var krevende å stå i, sier Maria." },
    { type: "paragraph", text: "Julie jobber på nyfødt intensivavdeling – en jobb som er krevende både fysisk og psykisk. Det å samtidig stå i en fertilitesprosess begynte å kjennes på." },
    { type: "paragraph", text: "Mellom det andre og tredje forsøket dro de på ferie til New York – kom hjem med skuldrene litt lenger nede. Da de satte i gang med tredje forsøk, ble det i samråd med Birgitte besluttet å sykemelde Julie." },
    { type: "quote", text: "– Birgitte hadde sagt at gjennomsnittlig tar det tre forsøk. Det stemte på en prikk for oss. Det tredje forsøket, i mai 2025, var det som til slutt satte seg, sier Julie." },
    { type: "paragraph", text: "De tok tidlige graviditetstester dag for dag og så streken bli tydeligere og tydeligere, helt det ikke var noe tvil lenger på at det var en graviditet. Allikevel ventet de en god stund med å annonsere graviditeten til de rundt dem, i frykt for at noe skulle gå galt igjen." },
    { type: "heading", text: "Emmy – født på farfars bursdag" },
    { type: "paragraph", text: "Emmy hadde termin på Valentines dagen, men kom to uker før termin, i 2026. Julie fødte på Ullevål – der hun selv har jobbet i åtte år. Maria var til stede gjennom hele fødselen." },
    { type: "quote", text: "– Det var en mektig opplevelse å ta del i. Å se Julie mestre fødselen med en slik ro over seg, var helt sinnssykt å bevitne. Jeg fikk løfte Emmy opp å legge henne på Julies bryst i det hun var født, og jeg fikk også klippe navlestrengen, sier Maria." },
    { type: "paragraph", text: "Da Maria sendte melding til foreldrene med nyheten, svarte faren: hun er jo født på farfars bursdag. Det siste som manglet falt på plass." },
    { type: "quote", text: "– Da var det selvfølgelig klart. Hun måtte hete Emmy etter farmoren min, sier Maria." },
    { type: "paragraph", text: "For Maria hadde navnevalget en ekstra betydning. Som barn til ved hjelp av donor fant hun i voksen alder ut at faren hun hadde vokst opp med, ikke var hennes biologiske far. Det var en tøff beskjed å få, men som også gjorde båndet mellom dem enda sterkere." },
    { type: "quote", text: "– Han er pappaen min, og en av mine største forbilder. Og det at Emmy ble født akkurat på farfars bursdag og fikk et navn fra farsiden, det var veldig rørende og meningsfylt. Vi hadde jo navnet “Emmy” på blokka, men da hun ble født på denne datoen ble det plutselig helt riktig at hun skulle hete det, sier hun." },
    { type: "paragraph", text: "I dag er Emmy fire måneder gammel, har akkurat lært å rulle og smiler masse." },
    { type: "quote", text: "– Vi elsker livet med Emmy, og forstår ikke hva livet var før henne. Sier Julie." },
    { type: "heading", text: "Råd til andre som vurderer det samme" },
    { type: "paragraph", text: "Maria og Julie er tydelige på at partnerdonasjon var riktig for dem, men at det finnes mange veier til å bli forelder, og man må gjøre det som føles riktig for seg selv." },
    { type: "quote", text: "– Gjør research og sett deg inn i mulighetene. Det vi valgte trenger ikke passe for alle. Lytt til magefølelsen din, og hva som kjennes riktig for nettopp deg, sier Julie." },
    { type: "paragraph", text: "Maria vil særlig understreke én ting:" },
    { type: "quote", text: "– Finn et sted der du føler at du blir sett. Det var det viktigste for oss. Et sted der alle spørsmål og bekymringer blir møtt med ro og respekt, uten at du må forklare hvem du er eller unnskylde for noe. Det har alt å si, sier hun." },
    { type: "paragraph", text: "Emmy er fire måneder gammel og bor i Oslo med sine to mødre. Maria Kathinca og Julie Bjørkvoll Rydeng deler historien sin i håp om at den kan inspirere andre som vurderer assistert befruktning." },
  ],

  "18-maneder-etter-hofteoperasjon-hos-cmedical": [
    { type: "heading", text: "Pasienthistorie:" },
    { type: "heading", text: "18 måneder etter hofteoperasjon hos CMedical sto hun på Sydpolen" },
    { type: "bold-intro", text: "«Mini og Muttern» er verdens første mor-datter-duo på Sydpolen. Etter 55 dager på ekspedisjon sto Emma «Mini» Gyllenhammar og moren Kathinka «Muttern» på verdens sørligste punkt." },
    { type: "quote", text: "– Det var enda mer spektakulært enn jeg hadde sett for meg, sier Emma." },
    { type: "paragraph", text: "For to år siden kunne hun knapt gå. Nå har hun gått 8-12 timer hver dag i over to måneder, med en pulk på over 100 kilo bak seg." },
    { type: "quote", text: "– Hvordan det gikk med hofta? Veldig bra, jeg hadde ikke vondt én eneste gang." },
    { type: "heading", text: "En mental utfordring" },
    { type: "paragraph", text: "Emma trodde det tøffeste skulle bli å nå frem til selve Sydpolen." },
    { type: "quote", text: "– Jeg var sikker på at jeg kom til å være utslitt og lei. Men da vi kom frem, følte jeg meg faktisk veldig bra. Vi var i en god flyt." },
    { type: "paragraph", text: "Den mentale kneiken kom tidligere, rundt dag 29, forteller hun." },
    { type: "quote", text: "– Vi hadde gått i en måned. Så slo det meg: Det er 45 dager igjen. Det var tungt. Du teller hele tiden – uker, timer og runde tall. Heldigvis er det konstante milepæler, og det var utrolig deilig å nyte en tid uten hverdagsstress og ting som venter på deg. Vi hadde ett mål, og det var å komme oss til Sydpolen sammen, og ikke minst ha det gøy på veien. Og det hadde vi, sier hun og legger til:" },
    { type: "quote", text: "– Ingenting overrasket oss. Vi hadde nok mat, sov godt og hadde varme nok klær. Mamma er ekstremt erfaren og nøye, og det har gjort meg nøye også." },
    { type: "heading", text: "55 dager. Ingen smerter." },
    { type: "paragraph", text: "For bare 18 måneder siden lå Emma på operasjonsbordet hos CMedical etter flere år med intense smerter. På en slik ekspedisjon er hoften spesielt utsatt når man trekker tung pulk dag etter dag." },
    { type: "quote", text: "– Det er egentlig helt utrolig at jeg i løpet av 55 dager ikke hadde vondt i hofta én eneste gang. Jeg var forberedt på at det kom til å gjøre vondt, og at jeg måtte gjøre øvelser underveis." },
    { type: "paragraph", text: "Hun stopper et øyeblikk." },
    { type: "quote", text: "– Det vitner om en ekstremt vellykket operasjon. Det var første gang på mange år at jeg kunne gjøre det jeg hadde lyst til, uten at det gjorde vondt. Det var helt magisk. Jeg er så takknemlig for at jeg møtte Kristian M. Warholm og det dedikerte teamet ved CMedical – de så meg, tok meg på alvor og bidro til en behandling som har forandret livet mitt." },
    { type: "paragraph", text: "Antarktis er nesten helt stille, og turen besto av både vind, whiteout og snøfall, men også sol." },
    { type: "quote", text: "– Det var ingen forstyrrelser. Bare oss to. Det er jo mange som ønsker å dra på ekspedisjon alene, men for meg var den største verdien å dele opplevelsen med mamma. Vi var så fokuserte på arbeidsoppgavene at været nesten ikke spilte noen rolle. Jeg var bare utrolig takknemlig for å være der. Jeg har brukt så mange år – og hofteoperasjoner – på å komme dit. Også er det jo ingenting som er varmere enn en mors trygghet." },
    { type: "paragraph", text: "På spørsmål om et av de sterkeste minnene, trekker hun frem en helt «vanlig» dag." },
    { type: "quote", text: "– Vi lå i teltet og drakk kakao etter dagens økt. Jeg tenkte bare på hvor heldig jeg var som fikk være der. Med mamma." },
    { type: "paragraph", text: "Kontrasten er stor. Fra å knapt kunne gå, til å gå 25 kilometer på ski hver dag i 55 dager." },
    { type: "quote", text: "– Jeg så hvor fort livet kan snu. Det gjør at jeg setter enda mer pris på det. For to år siden var det ingen garanti for at jeg skulle stå der." },
    { type: "paragraph", text: "Hun smiler." },
    { type: "quote", text: "– Nå vet jeg at det er mulig å komme tilbake." },
  ],

  "madeleine-engen-vinner-av-kvinnehelseprisen-her-awards-2026": [
    { type: "bold-intro", text: "CMedicals Kvinnehelse gründer og gynekolog Madeleine Engen er tildelt Kvinnehelseprisen under årets HER Conference & Awards – en av Norges fremste anerkjennelser for kvinnelige gründere." },
    { type: "paragraph", text: "Madeleine Engen vinner kvinnehelseprisenPrisen ble delt ut under HER Awards, arrangert av HER – Hun Etablerer Ressursprogrammet, ledet av Donna Kastrati. HER Awards er en hyllest til de bemerkelsesverdige kvinnene som har tatt risiko, utfordret normer og skapt en varig innvirkning gjennom sine selskaper." },
    { type: "heading", text: "Jurybegrunnelsen" },
    { type: "paragraph", text: "Juryen trakk særlig frem CMedicals helhetlige og spissede satsing på kvinnehelse gjennom hele livsløpet, og modellen med tverrfaglige ekspertteam innen gynekologiske sykdommer, kirurgi og fertilitetsbehandling – samlet under ett tak. En modell som gjør det mulig å møte kvinner der de er, med den kompetansen de faktisk trenger.Madeleine Engen vinner kvinnehelseprisen 2026" },
    { type: "heading", text: "Et kompetansesenter bygget på et kall" },
    { type: "paragraph", text: "Madeleine Engen er gynekolog med spesialisering innen urogynekologi og gründer av CMedical Kvinnehelse – med kompetansesentre i Oslo og Stockholm. Gjennom Instagram-kontoen @kvinnelegen når hun daglig ut til over 34 000 følgere med faktabasert kunnskap om kropp, helse og rettigheter, og bryter ned tabuer som lenge har holdt viktige samtaler tilbake.CMedical Kvinnehelse" },
    { type: "heading", text: "Behovet er reelt" },
    { type: "paragraph", text: "Realiteten Madeleine Engen kjemper mot er tydelig: kvinner lever 25 % av livet i dårligere helse enn menn, og i Norge er kvinner 74 % oftere sykemeldt. Ikke fordi de er svakere – men fordi kvinnehelse over tid har vært underprioritert, lavstatus og mangelfullt forsket på.CMedical ble bygget nettopp for å endre dette: ved å redusere tiden fra symptomer til diagnose og behandling, og gi kvinner et mer presist og tilgjengelig helsetilbud gjennom hele livet. Alle behandlere i CMedical er håndplukket med eget engasjement og hjerte for faget sitt." },
    { type: "heading", text: "Takk til alle som gjør det mulig" },
    { type: "paragraph", text: "Vi er utrolig takknemlige for at arbeidet vårt blir lagt merke til. Takk til alle samarbeidspartnere, ansatte i CMedical og våre pasienter som deler sine historier og inspirerer oss hver dag til å jobbe videre mot vårt mål: å bedre kvinnehelse i hele Norden, sier Madeleine Engen.Prisen er en anerkjennelse ikke bare av én person, men av et helt team og en bevegelse. Arbeidet fortsetter." },
  ],

  "overgangsalderen-er-en-ny-fase-ikke-slutten-pa-noe": [
    { type: "author", text: "Av Unni-Lovise Godager Berge, CMedical" },
    { type: "paragraph", text: "Symptomene på overgangsalderen starter ofte tidligere enn mange tror, som regel i første halvdel av 40-årene og opp til 10 år før menstruasjonen uteblir. For noen kvinner er overgangen knapt merkbar, mens andre opplever så store utfordringer at det påvirker både hverdagen og livskvaliteten." },
    { type: "quote", text: "– «Overgangsalderen er en naturlig del av livet, men for mange kan symptomene være både overveldende og forvirrende. Jeg møter mange kvinner som ikke helt forstår hva som skjer med kroppen deres, og som kanskje heller ikke blir tatt på alvor,» sier Birgitte Mitlid-Mork, gynekolog og spesialist i overgangsalder ved CMedical." },
    { type: "heading", text: "Store individuelle forskjeller" },
    { type: "paragraph", text: "De første tegnene kan ofte merkes gjennom uregelmessige menstruasjoner og hetetokter. Mange opplever også endringer i humør, søvnvansker og redusert energi." },
    { type: "quote", text: "– «Noen merker knapt at de går gjennom en hormonell endring, mens andre får symptomer som påvirker både jobb, familieliv og selvfølelse. Det er store individuelle forskjeller, og derfor finnes det heller ingen ‘one size fits all’-løsning,» forklarer Birgitte." },
    { type: "heading", text: "Vanlige symptomer inkluderer blant annet:" },
    { type: "list", items: ["Blødningsforstyrrelser", "Hetetokter og nattesvette", "Hjernetåke og konsentrasjonsvansker", "Søvnproblemer", "Emosjonell ustabilitet", "Smerter i muskler og ledd", "Endringer i hud og hår", "Redusert sexlyst og tørrhet i skjeden", "Mer enn bare hetetokter"] },
    { type: "paragraph", text: "Selve menopausen defineres som tidspunktet der menstruasjonen har uteblitt i 12 måneder. Men perioden før, den såkalte perimenopausen, kan vare i flere år." },
    { type: "quote", text: "– «Dette er en tid hvor hormonnivåene svinger, og det påvirker hele kroppen. Mange får symptomer som de ikke forbinder med overgangsalder, som angst, lavt energinivå eller smerter i kroppen,» sier Birgitte." },
    { type: "paragraph", text: "Hun understreker at nedgangen i østrogen, progesteron og testosteron ikke bare gir plager her og nå, men også kan øke risikoen for beinskjørhet, hjerte- og karsykdommer og depresjon på sikt." },
    { type: "quote", text: "– «Derfor er det viktig å ta symptomer på alvor, ikke bare for å bedre livskvaliteten, men også for å forebygge fremtidige helseproblemer,» sier hun." },
    { type: "paragraph", text: "Mange blir feildiagnostisert, og sendt hjem med medisiner for angst og depresjon, men så viser det seg at det er handler om overgangsalder, og symptomene må behandles på en helt annen måte." },
    { type: "heading", text: "Helhetlig behandling, skreddersydd for deg" },
    { type: "paragraph", text: "Hos CMedical tilbys en grundig kartleggingssamtale der kvinnens livssituasjon og helse gjennomgås i detalj. Samtalen varer i omtrent 45 minutter og inkluderer medisinsk vurdering, blodprøver ved behov og utarbeidelse av en personlig behandlingsplan." },
    { type: "quote", text: "– «Vårt mål er at hver pasient skal føle seg både sett og hørt, uansett hvilken fase i livet hun er i. Det finnes gode og trygge behandlingsalternativer som kan gi bedre livskvalitet og gjøre denne fasen lettere å håndtere,» forteller Birgitte." },
    { type: "paragraph", text: "Behandlingen kan også inkludere tverrfaglig samarbeid med andre fagpersoner hos CMedical, som ernæringsfysiolog, osteopat, psykolog eller sexolog, alt basert på den enkeltes behov." },
    { type: "heading", text: "Et tverrfaglig ekspertteam" },
    { type: "paragraph", text: "Ved CMedical møter pasientene et dedikert team av spesialister på overgangsalder: Ida Bjørntvedt, Birgitte Aspenes, Birgitte Mitlid-Mork og Madeleine Engen. Alle er medlemmer av British Menopause Society, og klinikken samarbeider med Newson Health i Storbritannia som er verdens ledende klinikk innen overgangsalder." },
    { type: "quote", text: "– «Vi jobber etter prinsippet om de fire søylene; hormoner, relasjoner, ernæring og fysisk form. Når disse delene balanseres, oppnår vi den beste helheten for pasientene våre,» forklarer Birgitte." },
    { type: "paragraph", text: "Et viktig budskap til alle kvinner– «Overgangsalderen handler ikke om å miste noe, men om å gå inn i en ny fase av livet. Med riktig kunnskap og behandling kan kvinner oppleve mer energi, bedre søvn, bedre humør, og større trygghet i egen kropp,» sier Birgitte Mitlid-Mork." },
  ],

  "nar-kroppen-ikke-fungerer-etter-fodsel-og-ingen-lytter": [
    { type: "author", text: "Av Madeleine Engen, gynekolog og gründer av CMedical kvinnehelse" },
    { type: "paragraph", text: "Jeg spesialiserte meg innen gynekologi med spesiell interesse og ekspertise innen vaginalt fremfall, fordi jeg var sjokkert over hvor mange kvinner som rammes og lider i stillhet. I hverdagen møter jeg kvinner helt ned i 20-årene som lever med nedpress (trykkende ubehag), vanskeligheter med å gå på do eller vannlatingstrang, en kropp som ikke lenger fungerer etter fødsel. De får ikke hjelp. Mange går i årevis uten å få diagnose, veiledning eller hjelp," },
    { type: "quote", text: "«Du må bare gjøre noen knipeøvelser», «Her er alt normalt, du har jo født, det er sånn det ser ut etter fødsel»" },
    { type: "paragraph", text: "Dette er ord mine pasienter har fått høre når de har bedt om hjelp, både fra offentlige og private helsetjenester. Holdninger som avslører et alvorlig kunnskapsgap i helsevesenet." },
    { type: "heading", text: "Vaginalt fremfall er en av de vanligste og mest oversette fødselsskadene." },
    { type: "paragraph", text: "Ifølge WHO får 36 prosent av kvinner som føder vaginalt permanente sekveler (ikke bare skader/det er psykisk også). Likevel er det mange som ikke blir tatt på alvor." },
    { type: "paragraph", text: "Vaginalt fremfall, også kalt underlivsprolaps, oppstår når skjedevegger, livmorhals eller livmor synker og buler inn eller ut av skjedeåpningen. Symptomene kan variere avhengig av skaden, fra nedpress, bulkfølelse, hyppig vannlating, vansker med å late vannet eller ved avføring, pinlige lyder fra skjeden eller redusert følelse under samleie. Bekkenbunnstrening under kyndig veiledning burde være et minimumstilbud. Men i mange tilfeller er kirurgi eneste vei til bedring." },
    { type: "heading", text: "Varsko om fallende fødselstall" },
    { type: "paragraph", text: "I media og fra politikere ropes det varsko om fallende fødselstall. Norge har i dag et av de laveste fruktbarhetstallene i Europa, og politikere slår alarm om at vi får altfor få barn til å opprettholde velferdssamfunnet. Eksperter etterlyser tiltak som kan snu utviklingen." },
    { type: "paragraph", text: "Årsaken til denne nedgangen er sammensatt, men vi kan ikke snakke om fødselstall uten å snakke om kvinnehelse. Vil en kvinne som fortsatt går rundt med ubehandlede fødselsskader etter første fødsel i det hele tatt vurdere å få sitt andre eller tredje barn?" },
    { type: "paragraph", text: "Vil vi øke fødselstallene, må vi ta kvinners helse før, og etter, fødsel på alvor. Det innebærer å ruste opp barsels- og etterfødselsomsorgen, sikre tidlig diagnostisering og behandling av fødselsskader, og heve kompetansen på dette området i helsevesenet." },
    { type: "paragraph", text: "I en årrekke var jeg selv plaget uten å få riktig hjelp ved en kvinnelidelse. Jeg vet hvordan det er å få feile diagnoser og behandlinger som gjør ting verre, hvordan tilliten svikter og mye kjennes håpløst. Først etter åtte år møtte jeg helsepersonell med riktig kompetanse på det som feilte meg, og da ble jeg frisk. Jeg er ikke alene om denne erfaringen. Det er rett og slett ikke godt nok." },
    { type: "paragraph", text: "Hvis vi virkelig vil ha flere barn i dette landet, burde vi ikke begynne med å ta vare på dem som faktisk føder barna? Før, under og etter." },
  ],

  "minis-historie-gjennom-mutterns-oyne": [
    { type: "paragraph", text: "For Kathinka «Muttern» Gyllenhammar er det å lede mennesker gjennom polare områder en del av jobben. Men ingenting kunne forberede henne på den reisen datteren Emma «Mini» skulle gjennom; fra hofteskade og operasjon, til rehabilitering og forberedelser til en av verdens tøffeste ekspedisjoner." },
    { type: "paragraph", text: "Emma var 17 år, aktiv fotballspiller og turjente med drømmer om å følge morens skispor mot Sydpolen. Men skaden i hoften satte alt på vent." },
    { type: "paragraph", text: "Les Emmas historie her: Fra operasjonsbordet til Sydpolen på 14 måneder" },
    { type: "quote", text: "– Det var forferdelig å se henne slik. Det er tungt å se en så aktiv unge få begrensninger. Vi prøvde alt, men da hun kom hjem fra USA, var hun ganske ødelagt. Det var første gang vi skjønte hvor alvorlig det var, forteller Kathinka." },
    { type: "paragraph", text: "Tidligere hadde Emma blitt operert uten at det ga ønsket resultat, snarere tvert imot. Smertene ble verre, og hverdagen stadig mer begrenset." },
    { type: "paragraph", text: "Da idrettskarrieren sto i ruiner fikk Emma rådet om å oppsøke ortopedkirurg Kristian Warholm ved CMedical, en erfaren spesialist innen hofteoperasjoner, også for idrettsutøvere. Det ble besluttet at Emma måtte opereres på nytt, og Kathinka kjente både frykt og lettelse." },
    { type: "quote", text: "– Jeg ble redd for at hun igjen skulle få falske forhåpninger, at det ikke skulle gå bra. Samtidig var jeg lettet over at noen faktisk så henne, og trodde hun kunne bli bedre. Det betydde alt, forteller hun." },
    { type: "paragraph", text: "Hun var selv på ekspedisjon på Grønland da Emma ble operert, og fulgte prosessen tett på avstand." },
    { type: "quote", text: "– Da jeg kom hjem, var både Emma og faren hennes utrolig fornøyde. De følte seg trygge og godt ivaretatt. Oppfølgingen fra både Kristian og CMedical har vært fantastisk i ettertid, sier hun." },
    { type: "paragraph", text: "Etter operasjonen gikk det fort. Bare måneder senere var Emma tilbake i full trening, og våren etter krysset hun Nordvestpassasjen sammen med moren, hele 400 kilometer over is og snø." },
    { type: "quote", text: "– Det betyr alt å se henne få livet tilbake. Hun har alltid vært en aktiv jente, og nå er hun tilbake der hun trives, med kroppen som fungerer. Det er helt fantastisk, sier Kathinka." },
    { type: "heading", text: "Mor og ekspedisjonsleder" },
    { type: "paragraph", text: "Mini og Muttern reiste i november 2025 og vil bli verdens første mor-datter-duo som når Sydpolen. For Kathinka betyr det en dobbel rolle, både som mor og ekspedisjonspartner." },
    { type: "quote", text: "– Det er stor forskjell på de rollene, men kanskje ikke så stor likevel. Jeg vil være den med mest erfaring der ute, men Emma har mye kunnskap hun også. Jeg vet hva hun kan, og hva jeg kan forvente. Den største forskjellen er kanskje at vi som familie vet hvilke knapper vi kan trykke på, sier hun med et smil og avslutter:" },
    { type: "quote", text: "– 75 dager i et lite telt blir både utfordrende og fantastisk. Vi har bare hverandre der ute og må ta vare på hverandre. Takk til CMedical for denne muligheten. Jeg gleder meg enormt, sier hun." },
    { type: "paragraph", text: "Les mer om hvordan de har forberedt seg her: Slik forbereder hun seg til Sydpolen" },
  ],

  "slik-forbereder-hun-seg-til-sydpolen": [
    { type: "paragraph", text: "Etter to år med intense smerter tross tidligere kirurgi måtte Emma «Mini» Gyllenhammar starte helt på nytt. Nå, etter en vellykket hofteoperasjon hos CMedical, trener hun systematisk mot et av verdens mest ekstreme mål: en polarekspedisjon til Sydpolen." },
    { type: "quote", text: "– Jeg tror fortsatt ikke helt at det skjer. Noe i meg tør ikke tro på det før jeg faktisk står der, sier hun." },
    { type: "paragraph", text: "Emma beskriver treningen som en reise i seg selv – en hun aldri ville vært i stand til å gjennomføre uten ny operasjon hos CMedical. Treningen består i stor grad av å trekke bildekk, både på asfalt og grus, for å simulere vekten av pulken hun skal dra etter seg gjennom snø og is." },
    { type: "quote", text: "– Først starter man med ett bildekk, så øker man til to, tre. Det er stor forskjell på underlaget, for eksempel er asfalt mye tyngre enn på grus. Siden jeg bor i byen, trener jeg mest på asfalt. I tillegg har jeg et litt annet utgangspunkt med hoften min som er operert, forteller hun." },
    { type: "paragraph", text: "Ifølge Emma står også yogaøvelser og badstue høyt på prioriteringslisten for å sikre god bevegelighet." },
    { type: "paragraph", text: "Man må kunne sitte bøyd i telt i 70 dager. Jeg har fortsatt noen svakheter i hoften, men det er ikke nærheten så ille som det var. Da hjelper det veldig med varmebehandling og gode yogaøvelser for hoften, forteller hun." },
    { type: "paragraph", text: "Kristian Marstrand Warholm er ortopeden bak den vellykkede operasjonen som ga hoftekulen bedre plass og bevegelighet. Han er både rørt og imponert over innsatsen Emma har lagt i rehabiliteringen." },
    { type: "quote", text: "– Historien til Emma viser hva moderne ortopedi kan utrette når kirurgi, riktig oppfølging og pasientens egen innsats spiller sammen. For oss på CMedical er det sterkt å se en pasient gå fra å knapt kunne gå, til å trene til Sydpolen på bare litt over et år, sier Warholm." },
    { type: "quote", text: "«Hvis du ikke er litt redd, har du gjort noe feil»" },
    { type: "paragraph", text: "Det er mye man må tenke på når man skal begi seg ut på en ekspedisjon til Sydpolen. Selv om Kathinka «Muttern» er en erfaren polfarer, er det visse bekymringer som ligger til grunn." },
    { type: "quote", text: "– Mamma sier alltid at hvis du ikke er litt redd, så har du gjort noe feil. Jeg er mest nervøs for hvordan kroppen takler det etter 30, 40, 50 dager, sier Emma." },
    { type: "paragraph", text: "Hun har gått lange ekspedisjoner før, blant annet gjennom Nordvestpassasjen, men aldri i 70 dager sammenhengende. Muttern er Norges første kvinnelige internasjonalt godkjente polarguide (IPGA), og har Grønland, Antarktis og Nordvestpassasjen som sine arbeidssteder." },
    { type: "quote", text: "– Det er ikke egentlig distansen eller kulden jeg er redd for. Det er usikkerheten i det langvarige. Hva skjer når man har gått på ski hver eneste dag i to måneder? Hva gjør det med kroppen? Hva gjør det med hodet?" },
    { type: "paragraph", text: "Når hun blir bedt om å si hva hun er mest redd for, kommer svaret kontant:" },
    { type: "quote", text: "– At teltet brenner." },
    { type: "paragraph", text: "Hun utdyper at dersom man søler bensin og det tar fyr, er det lite som kan redde deg på Sydpolen. Teltet er livsnerven. Mister du det, er det over." },
    { type: "quote", text: "– Eller at man faller i en bresprekk, og pulken treffer deg i hodet. Det finnes ingen hjelp der nede. Men vi følger sikre ruter, og mamma er ekstremt rutinert, så vi gjør alt vi kan for å minimere risikoen." },
    { type: "heading", text: "Kvinnehelse på tur" },
    { type: "paragraph", text: "I tillegg til ekstrem kulde og fysisk belastning, må kvinnelige polfarere ta høyde for utfordringer som sjelden snakkes om." },
    { type: "quote", text: "– Kvinner er mer utsatt for det som kalles polar thighs. Det begynner som små myggstikk på lår og rumpe, og kan utvikle seg til betente sår som må evakueres for. Det er derfor jeg går med dunshorts og dunskjørt hele tiden. Jeg skal ikke bli kald der, forteller Emma." },
    { type: "paragraph", text: "Hun snakker også om menstruasjon, som er krevende i et miljø hvor man ikke får vasket hendene på mange døgn." },
    { type: "quote", text: "– Tampax med applikator er det eneste som funker. Det selges lite i Norge, men du får tak i det. Det høres kanskje rart ut, men sånne detaljer kan utgjøre en enorm forskjell på tur." },
    { type: "paragraph", text: "Og så er det syklusen. Mens menn i stor grad våkner opp likt hver dag, går kvinner gjennom fire ulike hormonelle faser i løpet av en måned." },
    { type: "quote", text: "– Når vi er på tur i over to måneder, går vi gjennom hele den runden to ganger. Det påvirker energi, smerteopplevelse og følelser – alt. Men det er ikke noe man kan styre. Det er bare å jobbe med det, ikke mot det, sier Emma." },
    { type: "paragraph", text: "For Emma handler reisen ikke bare om å trene kroppen til en ekspedisjon i verdens tøffeste klima. Det handler også om å aldri gi opp når livet stanser opp." },
    { type: "quote", text: "– Aldri gi opp. Ikke ta et nei for et nei. Det finnes alltid en fagperson som kan hjelpe deg. For meg var det Kristian Warholm som virkelig så meg og trodde på at jeg kunne bli bedre. Det gjorde alt, sier Emma." },
  ],

  "fra-operasjonsbordet-til-sydpolen-pa-14-maneder": [
    { type: "paragraph", text: "Emma «Mini» Gyllenhammar var bare 17 år da alt raknet. En alvorlig hofteskade tok fra henne hverdagsglede og drømmen om å følge morens skispor til Sydpolen. Etter en mislykket operasjon levde hun i to år med konstante smerter, og et liv satt på vent. Men med hjelp fra CMedical fikk Emma livet tilbake. Nå forbereder seg til sitt livs største eventyr: å gå til Sydpolen med mamma «Muttern»." },
    { type: "paragraph", text: "Emma har alltid vært en eventyrer. Som tenåring deltok hun på ekspedisjoner sammen med moren Kathinka, Norges første kvinnelige internasjonalt godkjente polarguide (IPGA). Som 14-åring ble hun tidenes yngste til å fullføre det 100 km lange polare skiløpet Expedition Amundsen. Hun kombinerte en aktiv friluftsoppvekst med en lovende fotballkarriere, og som 17-åring tok hun laget sitt til seier i California State Championship-finalen." },
    { type: "paragraph", text: "Men bak suksessen lurte en skade. En hofteskade som brått satte en stopper for idrettsdrømmen." },
    { type: "quote", text: "– Jeg hadde alltid hatt smerter, men de ble holdt i sjakk med behandling. Til slutt fikk jeg beskjed om at det var nødvendig med en operasjon, og etter den første operasjonen i 2022 ble alt mye verre. Jeg klarte ikke å løpe, knapt å gå. Jeg følte kroppen min var ødelagt. Og drømmen om Sydpolen var plutselig knust, forteller Emma." },
    { type: "heading", text: "Vendepunktet hos CMedical" },
    { type: "paragraph", text: "Da idrettskarrieren sto i ruiner, fikk Emma rådet om å oppsøke kirurg Kristian Warholm ved CMedical. Han har lang erfaring med hofteoperasjoner, også på idrettsutøvere." },
    { type: "quote", text: "– Da jeg først møtte Emma, var hun på et dårlig sted. Hun var sterkt preget av smerter i hverdagen, og hadde mistet mye funksjon, forteller Warholm." },
    { type: "paragraph", text: "Under inngrepet fant han en tydelig årsak: hoftekulen passet ikke inn i hofteskålen." },
    { type: "quote", text: "– Dette er en type operasjon som krever spesialisert utstyr, riktig kompetanse og erfaring. Hofteleddet er et komplisert ledd, og når kulen ikke passer i skålen, blir hver bevegelse smertefull. Hos Emma var situasjonen ekstra utfordrende fordi hun hadde gått lenge med skaden. Vi visste vi måtte være svært presise for å gi henne funksjonen tilbake, sier han." },
    { type: "quote", text: "– Jeg var livredd. En tidligere mislykket hofteoperasjon hadde satt meg helt ut, og tanken på å gå gjennom det en gang til var nesten uutholdelig. Men etter gode og betryggende samtaler med Warholm våget jeg likevel. Inngrepet tok lenger tid enn planlagt fordi ingen visste helt hva som var galt, men jeg kjente med en gang etterpå at noe var annerledes. Smertene var borte, og det var som jeg hadde mer plass i hoften til bevegelse, sier hun." },
    { type: "paragraph", text: "Rehabiliteringen gikk raskt fremover. Allerede tre måneder etter operasjonen trente hun styrke, og innen jul var hun ute og dro dekk gatelangs. Våren etter gikk hun 400 km gjennom Nordvestpassasjen i Nord-Canada – over pakkis, skruis og temperaturer ned mot -40 grader – sammen med muttern." },
    { type: "quote", text: "– Å klare den turen, bare seks måneder etter operasjonen, ga meg en mestringsfølelse jeg aldri har kjent på før, sier Emma." },
    { type: "quote", text: "– Det aller viktigste har vært Emmas egen vilje og arbeid med opptreningen. Hun har vist en helt enorm innsats, og det er den kombinasjonen som gjør at hun står der hun gjør i dag, sier Warholm." },
    { type: "heading", text: "Mot Sydpolen" },
    { type: "paragraph", text: "I november 2025 reiser Emma og moren Kathinka ut på ekspedisjon. Sammen blir de verdens første mor-datter-duo til å gå til Sydpolen." },
    { type: "quote", text: "– Jeg trodde drømmen min var tapt. Men takket være CMedical og operasjonen fikk jeg en ny sjanse. Nå er jeg klar for mitt livs største eventyr." },
  ],

  "robotassistert-overvektskirurgi-presisjon-trygghet-og-varige-resultater": [
    { type: "paragraph", text: "Som den eneste private aktøren i Norden tilbyr CMedical robotassistert overvektskirurgi med høyeste presisjon og skånsomhet. Med avansert 3D-visualisering og mikrobevegelser styrt av erfarne kirurger, får du en trygg behandling som kan gi mindre smerter og raskere restitusjon." },
    { type: "heading", text: "Hva er robotassistert sleeve gastrektomi (rSG)?" },
    { type: "paragraph", text: "Slankeoperasjon med Sleeve gastrektomi er en moderne metode der 60–80 % av magesekken fjernes. Den gjenværende delen formes til en bananformet \"sleeve\", som gjør at du får mindre sultfølelse, spiser mindre og oppnår varig vektreduksjon, uten å gå på kompromiss med kroppens evne til å ta opp næringsstoffer." },
    { type: "paragraph", text: "Robotassistert teknikk gjør prosedyren mer presis enn tradisjonell laparoskopi. Kirurgen styrer hele inngrepet fra en konsoll, og avansert teknologi oversetter hånd- og fingerbevegelser til mikrobevegelser i instrumentene." },
    { type: "quote", text: "– Det er viktig å understreke at det ikke er en robot som opererer deg. Hele prosedyren styres av en erfaren kirurg – teknologien gir oss bare enda større presisjon og kontroll, forklarer Dr. Jan Roland Lambrecht, fagansvarlig gastrokirurg hos CMedical." },
    { type: "heading", text: "Fordeler med robotassistert kirurgi" },
    { type: "list", items: ["**Mindre smerter** og kortere restitusjonstid", "**Redusert blodtap** og færre komplikasjoner", "**Bedre kosmetisk resultat** gjennom små snitt", "**Raskere tilbake i hverdagen** – mange reiser hjem dagen etter operasjonen", "**Kortere sykemelding** – ofte bare to uker"] },
    { type: "paragraph", text: "Etter ett år kan pasienter som gjennomgår sleeve gastrektomi forvente et vekttap på 20-25 % av total kroppsvekt samt varig forbedring av helserelatert livskvalitet." },
    { type: "quote", text: "– Mange pasienter opplever at dette blir starten på et nytt liv – med mer energi, bedre helse og en hverdag der vekten ikke lenger er en barriere, sier Dr. Andreas Edenberg, spesialist i gastroenterologisk kirurgi og en del av CMedicals tverrfaglige team." },
    { type: "heading", text: "Trygg behandling hos erfarne spesialister" },
    { type: "paragraph", text: "CMedical har over 7 års erfaring med robotassisterte inngrep, og våre kirurger kombinerer høy faglig presisjon med tett oppfølging." },
    { type: "list", items: ["**Dr. Jan Roland Lambrecht** har over 25 års erfaring fra Norge og Danmark, og er en anerkjent ekspert innen overvektskirurgi, brokkirurgi og robotassistert kirurgi. Han er også engasjert i utdanning av neste generasjons kirurger.", "**Dr. Andreas Edenberg** er spesialist i generell- og gastrokirurgi, med særlig kompetanse på fedmebehandling og avansert endoskopi. Han følger deg tett før og etter operasjonen, og hjelper deg med en individuell plan for vektreduksjon og bedre helse."] },
    { type: "heading", text: "Forberedelser og oppfølging" },
    { type: "paragraph", text: "Godt forarbeid gir best resultat. Før operasjonen vil du møte vårt tverrfaglige team, inkludert ernæringsfysiolog, som veileder deg i kosthold og livsstilsendringer. Blant annet anbefales en lavkaloridiett i tre uker før inngrepet for å gjøre operasjonen enklere og tryggere." },
    { type: "paragraph", text: "Etter operasjonen får du tett oppfølging og støtte, slik at du lykkes med varige endringer i kosthold og livsstil." },
    { type: "quote", text: "– For oss handler det ikke bare om selve inngrepet, men om å gi pasientene de riktige verktøyene for å oppnå et stabilt og sunt vekttap. Trygghet, presisjon og oppfølging står i sentrum, understreker Jan Roland Lambrecht." },
    { type: "heading", text: "Ta det første steget" },
    { type: "paragraph", text: "Vil du vite mer om hvordan en sleeve gastrektomi kan hjelpe deg med vektreduksjon og økt livskvalitet? Hos CMedical får du en uforpliktende samtale med en av våre erfarne kirurger – der du får svar på spørsmål, realistiske forventninger og en plan som passer deg." },
    { type: "bold-intro", text: "Ta det første steget mot en enklere hverdag og økt livskvalitet – bestill en gratis konsultasjon med Dr. Andreas Edenberg [her](https://cmedical.no/no/spesialister/andreas-edenberg)." },
    { type: "paragraph", text: "Ønsker du mer informasjon om Overvektskirurgi, les mer her." },
  ],

  "livio-oslo-blir-en-del-av-cmedical-og-tilbudet-til-pasientene-styrkes": [
    { type: "paragraph", text: "I 1986 åpnet den første private fertilitetsklinikken i Norge. Livio Oslo – den gang kjent som IVF-klinikken – har siden vært en pioner innen assistert befruktning. Gjennom snart 40 år har klinikken bidratt til at over 3500 barn har kommet til verden." },
    { type: "paragraph", text: "Nå har Livio Oslo blitt en del av CMedical, og pasientene får tilgang til en unik kombinasjon av moderne teknologi, kirurgisk kompetanse og lang erfaring innen fertilitetsbehandling." },
    { type: "paragraph", text: "«Fordelene med at vi nå slår oss sammen er at pasientene får tilgang til et bredere behandlingstilbud, flere spesialister på samme sted, samt god kompetanse og teknologi fra begge klinikker», sier Kjersti Brenden, gynekolog og fertilitetsspesialist fra Livio Oslo." },
    { type: "heading", text: "En unik kombinasjon" },
    { type: "paragraph", text: "CMedical er den første klinikken i Norden som samler fertilitetsbehandling og kirurgi under samme tak. Med toppmoderne utstyr, en høytekonolgisk fertilitetslab og et bredt tverrfaglig team, blir behandlingen helhetlig og trygg – fra pubertet og graviditet til barseltid og tiden etter fødsel." },
    { type: "paragraph", text: "«Med topp moderne teknologi og fertilitetsbevarende robotkirurgi kan vi tilby en mer helhetlig omsorg og behandling av en utfordring som kan være kompleks. Dette gir trygghet underveis – noe som skiller oss ut i et felt hvor presisjon og samarbeid på tvers er avgjørende», sier Birgitte Mitlid-Mork, Gynekolog og fertilitetsspesialist fra CMedical." },
    { type: "heading", text: "Erfaring som bygger trygghet" },
    { type: "paragraph", text: "Livio Oslo har vært en viktig aktør i norsk fertilitetshistorie, og bringer med seg nesten fire tiår med erfaring." },
    { type: "paragraph", text: "«De viktigste erfaringene vi har gjort oss etter snart 40 år med fertilitetsbehandling er at utvikling over tid har gitt trygghet og erfaring. Vi har hele tiden hatt fokus på individualisert pasientoppfølging», forteller Kjersti." },
    { type: "paragraph", text: "Denne erfaringen kombinert med CMedicals teknologiske satsing skaper et unikt utgangspunkt for pasientene." },
    { type: "heading", text: "Flere søker behandling i dag" },
    { type: "paragraph", text: "Ufrivillig barnløshet rammer mellom 8–12 % av par i Norge. Samtidig ser man at flere søker hjelp i dag enn tidligere – både på grunn av økt åpenhet og endringer i lovverket." },
    { type: "paragraph", text: "«Holdningene til assistert befruktning har blitt mye mindre tabubelagt enn før. Når man spør, kjenner nesten alle noen som har vært gjennom en behandling. Ofte er det gjennom disse erfaringene fra bekjente at pasientene finner veien til oss», sier Birgitte." },
    { type: "heading", text: "Et bredt tverrfaglig tilbud" },
    { type: "paragraph", text: "Et særpreg ved CMedical er bredden i tilbudet. Klinikken har spesialister på sykdommer som rammer mange infertile, som PCOS og endometriose, og et eget ekspertteam på avansert endometriosekirurgi." },
    { type: "paragraph", text: "«Vi følger pasienten tett før, under og etter fertilitetsprosessen. I tillegg til fertilitetsbehandlingen tilbyr vi oppfølging fra fostermedisinere, fødselsleger, bekkebunnsosteopater og gynekologer med kompetanse på fødselsskader. Vi har også et bredt tverrfaglig team bestående av fertilitetscoach, ernæringsfysiolog, sexolog og psykolog – alt under samme tak. Dette er helt unikt», understreker Birgitte." },
    { type: "heading", text: "Fordelene for pasientene" },
    { type: "paragraph", text: "At Livio Oslo og CMedical nå samler kreftene, gir pasientene en rekke konkrete fordeler: kortere ventetid, større kapasitet og et styrket tilbud innen både fertilitet og kirurgi." },
    { type: "paragraph", text: "«Pasientene vil oppleve et styrket tilbud, blant annet innen mannlig infertilitet, inkludert Micro-TESE, og raske polikliniske undersøkelser uten ventetid. Alt dette kombinert med en høyteknologisk fertilitetslab og tverrfaglig oppfølging før, under og etter behandling», forklarer Kjersti." },
    { type: "heading", text: "Et tryggere behandlingsløp" },
    { type: "paragraph", text: "Kirurgisk kompetanse under samme tak gir nye muligheter for pasientene." },
    { type: "paragraph", text: "«Det betyr at vi kan fjerne polypper, muskelknuter eller åpne livmorhalsen før IVF. Vi er den eneste private aktøren som som tilbyr avansert fertilitetsbevarende kirurgi med robot. Dette gjør fertilitetsreisen enklere og tryggere – med mindre stress», sier Birgitte" },
    { type: "heading", text: "Det beste fra to verdener" },
    { type: "paragraph", text: "Med Livio Oslo og CMedical sammen får pasientene en kombinasjon av erfaring, trygghet og moderne teknologi – alt samlet på ett sted. Dette gir pasientene et helhetlig og fremtidsrettet tilbud, der både kropp og sinn blir ivaretatt." },
  ],

  "historiene-ingen-snakker-om-etter-fodsel": [
    { type: "paragraph", text: "For mange kvinner er det krevende å snakke om plager etter fødsel. Skader kan være usynlige utad, men likevel sette dype spor både fysisk og psykisk." },
    { type: "paragraph", text: "«Astrid» (50) er en av mange som har opplevd dette, og som til slutt fant hjelpen hun trengte hos vår gynekolog, Madeleine Engen." },
    { type: "paragraph", text: "I en artikkel publisert i Nettavisen forteller «Astrid» om en lang reise fra fødselsskade til flere operasjoner, og hvordan møtet med Madeleine til slutt ble vendepunktet. «Astrid» ønsker å være anonym pga skammen hun opplever preger denne type helseproblematikk." },
    { type: "heading", text: "Mange år med smerter og usynlige skader" },
    { type: "paragraph", text: "Etter fødselen av sitt første barn i 2000 fikk hun beskjed om at smertene og plagene hun opplevde var «helt normale». Selv da muskulaturen innvendig var helt revnet, ble hun møtt med råd om knipeøvelser. Først etter en privat operasjon to år senere fikk hun livet tilbake – men anbefalingen var at hun måtte gjennomføre en ny operasjon senere i livet." },
    { type: "paragraph", text: "Da hun høsten 2024 fulgte dette rådet, ble resultatet det motsatte: Smertene ble verre enn noen gang, og hun endte opp på krykker. For «Astrid» ble dette starten på en tung periode der hverdagen føltes umulig å håndtere." },
    { type: "heading", text: "Fant hjelpen hos CMedical" },
    { type: "paragraph", text: "Vinteren 2025 kom hun til CMedical, og møtte Madeleine Engen – gynekolog med særlig kompetanse på fødselsskader. For første gang på mange år følte hun seg sett og forstått." },
    { type: "quote", text: "– Hun kom til oss som en svært traumatisert pasient. Skadene hennes var så omfattende at jeg først trodde hun aldri hadde vært operert, forteller Madeleine." },
    { type: "paragraph", text: "Engen rekonstruerte muskulaturen i mellomkjøttet, slik at bekkenbunnen igjen fikk støtte og hold. Allerede kort tid etter operasjonen kunne «Astrid» legge bort krykkene. Nerveskaden hun hadde fått fra en tidligere operasjon lot seg ikke reparere, men smertene hun sto igjen med ble håndterbare." },
    { type: "heading", text: "Behovet for et løft i kvinnehelse" },
    { type: "paragraph", text: "For «Astrid» ble opplevelsen livsendrende, men hun understreker at det sjokkerende er hvor mange andre som deler lignende historier." },
    { type: "quote", text: "– Jeg ønsker å fortelle min historie fordi jeg vet det er mange flere der ute. Altfor mange kvinner lever med plager de ikke skulle hatt, sier hun til Nettavisen." },
    { type: "paragraph", text: "For Madeleine Engen er dette dessverre en kjent situasjon." },
    { type: "quote", text: "– Altfor mange kvinner blir bagatellisert eller feilbehandlet. Vi skylder kvinner mer enn dette. Kompetansen på kvinnehelse må styrkes, sier hun." },
    { type: "heading", text: "Et felles ansvar" },
    { type: "paragraph", text: "Hos CMedical møter vi daglig kvinner med alt fra fødselsskader til endometriose og overgangsplager. Vårt mål er å tilby høyeste faglige kompetanse og omsorg, slik at ingen skal stå alene med sine utfordringer." },
    { type: "paragraph", text: "Historier som «Astrid» sin viser hvorfor dette arbeidet er så viktig – og hvorfor kvinnehelse må tas på alvor på alle nivåer i helsetjenesten." },
    { type: "paragraph", text: "Kilde: Nettavisen, 2025 «Privatklinikk ble siste utvei: – Reddet livet mitt»" },
  ],

  "jeg-matte-grate-pa-telefonen-for-a-bli-tatt-pa-alvor": [
    { type: "bold-intro", text: "Da Kristine fikk sin første sønn, forventet hun en normal tilhelingsprosess. Men smertene var uutholdelige, til og med en enkel trilletur ble umulig. – Jeg visste at noe var galt, men ingen ville høre på meg. Jeg hørte gang på gang at dette var helt normalt, sier Kristine Flygind Bjerke." },
    { type: "paragraph", text: "Hun forteller videre at hun gjennom flere måneder oppsøkte både private og offentlige spesialister i håp om å få svar, men ingen fant noe galt." },
    { type: "quote", text: "– Det føltes som om underlivet mitt var på vei ut. En helt utrolig ubehagelig følelse som snudde livet mitt på hodet. Jeg klarte ikke å være den mammaen jeg ønsket å være, og jeg så mitt aktive liv forsvinne. «Er det virkelig sånn jeg skal leve?», husker jeg at jeg tenkte, forteller Bjerke." },
    { type: "heading", text: "– Følte meg som en kasteball" },
    { type: "paragraph", text: "De første to ukene etter fødselen var svært smertefulle. I desperasjon ringte Kristine sykehuset, men fikk beskjed om at «returretten» – retten til å komme tilbake for undersøkelse og oppfølging ved komplikasjoner – var utløpt etter 14 dager. Hun ringte på dag 16." },
    { type: "quote", text: "– Jeg følte meg som en kasteball og ble hele tiden henvist videre, men ingen kunne si noe konkret. Til slutt måtte jeg gråte på telefonen for å få hjelp, sier hun." },
    { type: "paragraph", text: "Hun fikk til slutt en ny time, men igjen fikk hun beskjed om at alt var i orden." },
    { type: "quote", text: "– Denne dagen ble jeg kjørt til sykehuset fordi jeg ikke klarte å sitte ordentlig og kjøre selv. Smertene var så intense. Det føltes som et slag i ansiktet å bli sendt hjem igjen, sier Bjerke." },
    { type: "heading", text: "Ble deprimert av smertene" },
    { type: "paragraph", text: "Etter hvert mistet Kristine troen på at noen kunne hjelpe henne. Hun hadde senere vært hos fire leger som sa at alt var normalt. Hun beskriver det som et mentalt mørke der følelsen av å ikke bli trodd og ikke få hjelp ble like tung å bære som selve smertene." },
    { type: "quote", text: "– Det ødela så mye. Ikke bare kroppen, men hele identiteten min. Jeg følte jeg ble fratatt muligheten til å være til stede for barnet mitt. Jeg klarte ikke å «nyte barseltiden», slik alle sa at jeg skulle. Det var vondt å høre, for jeg ville jo det, men jeg hadde altfor sterke smerter, sier hun." },
    { type: "paragraph", text: "Først etter 15 måneder kom hun til gynekolog Madeleine Engen hos CMedical, og allerede ved første konsultasjon forstod Madeleine hva problemet var." },
    { type: "quote", text: "– Jeg begynte å gråte da jeg kom til henne. Jeg var så redd for at hun også skulle si at alt var normalt. Men hun så problemet med én gang. Det var en lettelse jeg ikke kan beskrive, sier Bjerke." },
    { type: "paragraph", text: "To uker senere ble Kristine operert for vaginalt fremfall. Ifølge Engen er dette en historie som stadig gjentar seg." },
    { type: "quote", text: "– Dessverre er ikke Kristines historie unik. Bekkenbunnstrening er viktig, men det holder ikke å få beskjed om «å bare knipe», det bør gjøres med veiledning av en osteopat eller fysioterapeut som er eksperter på bekkenbunn. Hvis skadene er for dype, er operasjon løsningen. Det kan ofte oppleves som tabubelagt å snakke om hvordan underlivet føles etter en fødsel. Mye er nytt og annerledes, og man er veldig sårbar. Derfor er det så viktig at det blir tatt på alvor. Ingen ønsker å eksponere seg slik hvis det ikke er nødvendig, sier Madeleine Engen, gynekolog og gründer av CMedical." },
    { type: "paragraph", text: "Kristine forteller at den vedvarende smerten og mangelen på hjelp tømte henne fullstendig mentalt." },
    { type: "quote", text: "– Jeg har aldri vært sykemeldt før, men etter operasjonen kom det en reaksjon jeg ikke var forberedt på. Da kroppen begynte å fungere igjen, kom alt det psykiske. Jeg måtte bearbeide det jeg hadde stått i, og det tok tid. Jeg klarte ikke å gå tilbake på jobb. Jeg ville ikke se kolleger, ikke snakke om hvordan jeg hadde det. Jeg trengte å bygge meg opp på nytt, sier hun." },
    { type: "paragraph", text: "I dag har Bjerke fått livet sitt tilbake, men hun reagerer på hvor lite fokus det er på kvinnehelse etter fødsel – både fysisk og psykisk." },
    { type: "quote", text: "– Vi forberedes på graviditet og fødsel, men ingen snakker om hvor vanskelig tiden etterpå kan være. Det føles som om systemet bare slipper taket i oss etter at babyen er ute, sier hun." },
    { type: "paragraph", text: "Hun mener at helsetjenesten har alt å vinne på å gi kvinner raskere og bedre behandling." },
    { type: "quote", text: "– Sykemelding i et halvt år koster samfunnet mye. Det burde være like viktig å ivareta mødrene som barna. Jeg håper at en større åpenhet fremover kan bidra til å hjelpe flere der ute. Jeg er vanligvis en som hører på legen, noe man trygt skal kunne gjøre, men i dette tilfellet kunne jeg rett og slett ikke det. Det er veldig skremmende å tenke på alle de som gir opp og bare lever med smertene, avslutter hun." },
    { type: "heading", text: "Vaginalt fremfall" },
    { type: "paragraph", text: "Vaginalt fremfall, også kalt underlivsprolaps, oppstår når skjedevegger, livmorhals eller livmor synker og buler inn eller ut av skjedeåpningen. Dette skyldes at strukturer som muskulatur og bindevev har blitt strukket og skadet under fødselen. Omtrent 1 av 3 kvinner som har født opplever en grad av vaginalt fremfall, men ikke alle har symptomer. Symptomene kan variere avhengig av skaden fra nedpress, bulkfølelse, hyppig vannlating, vansker med å late vannet eller ved avføring, smerter eller redusert følelse under samleie." },
    { type: "paragraph", text: "Vaginalt fremfall er vanlig, men fortsatt underkommunisert når det kommer til både diagnostikk og det å veilede kvinnene til riktig behandling – og for mange en utfordring som går utover både livskvalitet og velvære." },
    { type: "paragraph", text: "Se historien til Kristine, omtalt i Nettavisen 17\\. september." },
  ],

  "maria-falt-i-sahara-og-mellom-alle-stoler-i-helse-norge": [
    { type: "bold-intro", text: "Et uhell i Sahara i februar 2024 ble starten på et år fylt av smerte, mistillit og en kamp mot systemet. Nå vil Maria Teresa Cristofoli (54) løfte en stemme for de som ikke blir sett i det offentlige helsevesenet. – De som er sykemeldt over en lang periode, velger det ikke alltid selv, sier hun." },
    { type: "paragraph", text: "Det begynte med en aktiv ferie i Sahara. Maria er typen som trives med fysisk utfordring og eventyr, og bestemte seg for å buldre i ørkenen. Et feiltrinn endte med et brudd i høyrehånden og en dramatisk evakuering til et lokalt sykehus. Gips og en lang hjemreise senere, var hun tilbake i Norge – og inn i et behandlingsforløp hun aldri hadde sett for seg. Hun ble operert dagen etter." },
    { type: "quote", text: "– Jeg hadde aldri brukket noe før, og stolte fullt og helt på at jeg var i trygge hender. Men da gipsen kom av etter tre uker og hånden så ut som voks, kjente jeg det første stikket av panikk. Og det skulle bare bli starten, sier hun." },
    { type: "heading", text: "En hånd som aldri ble bra" },
    { type: "paragraph", text: "På kontroll fikk Maria beskjed om at hevelsen og smerten ville gå over. Hun skulle ikke belaste hånden og deretter komme på ny kontroll om tre uker. Først da fikk hun endelig møte en lege." },
    { type: "quote", text: "– Men, jeg ble satt i bås. En aktiv kvinne med masse driv ble plutselig redusert til en vanskelig pasient, sier hun." },
    { type: "paragraph", text: "Hun måtte kjempe for å bli tatt på alvor, og etter hvert kom hun til en fysioterapeut som stoppet opp behandlingen umiddelbart, og kontaktet lege på nytt." },
    { type: "quote", text: "– Det var ikke vits å begynne med øvelser slik hånden så ut." },
    { type: "paragraph", text: "Men videre fremdrift måtte Maria mase seg til: ekstra røntgenbilder og nye vurderinger. Hun hadde så sterke smerter at det ble vanskelig å møte opp på jobben som salgsdirektør, og var desperat etter å få hjelp. Etter hvert fikk hun beskjed om at det skulle holdes et kirurgmøte hvor en ny operasjon kunne vurderes – men først om seks uker." },
    { type: "quote", text: "– Seks uker med usikkerhet og venting. Så kom telefonen, de ville ikke gjøre noe før i februar. Jeg skulle bare vente og ett år hadde allerede gått med sterke smerter og sykemeldinger, sier Maria." },
    { type: "heading", text: "Vendepunktet" },
    { type: "paragraph", text: "Et vendepunkt kom da Maria i ventetiden valgte å bruke arbeidsgivers helseforsikring. Hun oppsøkte kirurg Jan-Ragnar Haugstvedt ved CMedical, en hun hadde hørt mye godt om. Der ble det tatt nye bilder, og han kunne raskt slå fast at benet under platen som var operert inn, ikke hadde grodd riktig." },
    { type: "quote", text: "– Endelig følte jeg at noen så Maria: som har lyst til å jobbe 100 prosent igjen, som har lyst til å gå på ski og gjøre alle de tingene hun pleide å gjøre. Som ikke bare var en brikke i et stort offentlig apparat, sier hun og legger til:" },
    { type: "quote", text: "– Her fikk jeg troen på at jeg skulle få livet mitt tilbake." },
    { type: "paragraph", text: "Ifølge Maria var Haugstvedt tydelig på at skaden var omfattende, men forsikret henne om at hun sannsynligvis kom til å bli bra igjen." },
    { type: "quote", text: "– Han sa til og med etter operasjonen at skaden var enda større enn han først antok. Det var tett oppfølging, kommunikasjonen var tydelig og kirurgen var støttende. Nå forsto jeg virkelig verdien av å faktisk ha tid til pasienten, trygghet og ikke minst resultat, sier Maria." },
    { type: "paragraph", text: "Smertene avtok, og hånden fungerte – om ikke perfekt – igjen." },
    { type: "quote", text: "– Et brudd vil normalt gro i løpet av seks uker. Når det ikke skjer, som i dette tilfellet, er det avgjørende å oppdage det i tide. Her måtte vi transplantere bein for å få bruddet til å gro. Å utsette en slik operasjon kan få alvorlige konsekvenser og frata pasienten både funksjon og livskvalitet, sier Jan-Ragnar Haugstvedt." },
    { type: "heading", text: "En ripe i lakken for det offentlige" },
    { type: "paragraph", text: "Maria beskriver året som sitt «annerledes-år». Et år som har satt ting i perspektiv – om verdighet, behandling og hvordan systemet behandler de som faller utenfor." },
    { type: "quote", text: "– Jeg har følt meg som en belastning. Som en kost/nytte-sak. Og det skremmer meg, for hva med de som er enda sykere, mer sårbare, som ikke har ressursene til å stå på sitt?" },
    { type: "paragraph", text: "Hun peker på et større paradoks i møte med dagens samfunnsdebatt:" },
    { type: "quote", text: "– Denne saken er en ripe i lakken for det offentlige Norge. Når det pågår en sykefraværsdebatt samtidig, så er det et paradoks. Det er ikke alle sykemeldte som har valgt det selv. Noen av oss har bare hatt ekstremt uflaks, sier hun." },
    { type: "paragraph", text: "Maria har nå en ny hverdag og kan endelig leve et aktivt liv igjen. Men historien hennes blir stående som en påminnelse om at det å bli sett og tatt på alvor kan være forskjellen på å bli frisk – eller bli stående fast." },
  ],

  "cmedical-og-nors-care-inngar-samarbeid-vil-styrke-kvinners-kunnskap-om-egen-helse": [
    { type: "bold-intro", text: "CMedical, som har Nordens mest komplette private kvinnehelsetilbud, og Nørs Care, som står bak Norges største kvinnehelseapp Nørs, har inngått en strategisk samarbeidsavtale med mål om å øke kunnskapen om fertilitet blant kvinner." },
    { type: "paragraph", text: "Kvinnehelseappen Nørs står sterkt blant gravide og de som nylig har født i Norge og har over 200 000 kvinnelige brukere. Nå skal innholdet i Nørs breddes ut og hjelpe kvinner gjennom hele livet, fra første menstruasjon oppstår til og med overgangsalder. Allerede i dag er det mange kvinner som har behov for informasjon og kunnskap rundt fertilitet som bruker Nørs for å orientere seg. Nå skal CMedicals ekspertteam på fertilitet, bidra til å utvide og kvalitetssikre det faglige innholdet på plattformen. Dette gir Nørs-brukerne trygghet, kunnskap og bedre grunnlag for å ta informerte beslutninger." },
    { type: "quote", text: "– Vi har et sterkt fagmiljø innen fertilitet, både i Norge og i Sverige. Tidligere i år styrket vi satsningen på fertilitet ytterligere gjennom oppkjøpet av Livio Oslo, Norges eldste private fertilitetsklinikk. Vi opplever at behovet for kunnskapsbasert og tilgjengelig informasjon om fertilitet er stort, og vi ønsker å bidra til å styrke helsekompetansen hos kvinner i fertil alder, sier Unni-Lovise Godager Berge, fungerende Markedsdirektør i CMedical." },
    { type: "paragraph", text: "For Nørs Care er samarbeidet med CMedical en viktig bidragsyter i å sikre faglig kvalitet og legitimitet i innholdet på plattformen. Med eksperter på laget kan Nørs tilby brukerne kunnskap som er både tilgjengelig og medisinsk fundert – en kombinasjon som er avgjørende i dagens digitale helselandskap." },
    { type: "quote", text: "– Sammen skal CMedical og Nors Care bidra til å tette kunnskapsgapet innen kvinnehelse og fertilitet. CMedicals sterke fagmiljø vil være en viktig ressurs for oss, samtidig som våre teknologiske løsninger vil kunne bidra til å styrke CMedicals pasientreiser, sier Alexander Rein, en av grunnleggerne av Nors Care." },
    { type: "heading", text: "Oppsøk hjelp før det går for lang tid" },
    { type: "paragraph", text: "CMedical erfarer at mange som sliter med å bli gravide går for lenge uten å oppsøke hjelp eller forstå hva som kan være utfordringene. De håper at terskelen for å ta kontakt senkes ved å spre kunnskap og å være til stede i en digital plattform som mange bruker." },
    { type: "quote", text: "– I denne plattformen har vi mulighet til å nå kvinner og par i en tidlig fase der de har et barneønske. Vi kan bidra til å belyse eventuelle utfordringer man kan oppleve rundt det å bli gravid. Videre kan dette føre til at de som sliter oppsøker hjelp raskere. De vil samtidig komme til oss med bedre kunnskap, stille gode spørsmål og får mer ut av konsultasjonen. Dette vil bidra til god og målrettet behandling, sier Gynekolog og fertilitetsspesialist ved CMedical, Birgitte Mitlid-Mork." },
    { type: "quote", text: "– Der vi ser det kan være nødvendig, har vi i tillegg til fertilitetsbehandling gode muligheter for fertilitetsbevarende tiltak, med blant annet robotassistert kirurgi som den eneste private aktøren i Norge, avslutter hun." },
  ],

  "cmedical-kjoper-livio-oslo": [
    { type: "bold-intro", text: "CMedical satser ytterligere på kvinnehelse og fertilitetsbehandling, og kjøper opp Livio Oslo, landets første private fertilitetsklinikk og første klinikk med egen egg- og sædbank, på Majorstua i Oslo." },
    { type: "paragraph", text: "CMedical er Nordens ledende private aktør innen kvinnehelse. Selskapets fertilitetsklinikk er innovativ, med det siste innen teknologisk utstyr og et svært kompetent fertilitetsteam, med internasjonal erfaring. Med Livio Oslos lange erfaring og tunge posisjon i Norge vil CMedical nå bli en enda større aktør i det norske markedet for fertilitetsbehandlinger. I tillegg vil vi nå kunne tilby både sæd- og eggdonasjon fra norske donorer." },
    { type: "quote", text: "– Kvinnehelse og fertilitetsbehandling har vært et uttalt satsingsområde for CMedical siden 2022 og vi ser et stort potensial for vekst. Fra juni 2025 får vi større kapasitet og muligheten til å hjelpe langt flere med å oppnå drømmen om å få barn. Vi gleder oss veldig til å få styrket tjenestene våre med enda flere faglig sterke, erfarne og kompetente medarbeidere, sier Anne Flo, CEO i CMedical Norge." },
    { type: "paragraph", text: "CMedical og Livio Oslo holder til i samme bygg på Majorstua, og Flo ser det som en naturlig utvidelse av miljøet på huset når selskapene etter hvert slås sammen." },
    { type: "quote", text: "– Vi er begeistret over at det er CMedical som kjøper opp den Norske delen av Livio, slik at tilbudet blir godt ivaretatt videre. CMedical er et selskap som satser offensivt på reproduktiv helse. Pasientene vi har i dag vil ikke merke noe til endringene og kan forholde seg til Livio Oslo som før, og på sikt er jeg sikker på at flere pasienter vil kunne dra nytte av et enda større miljø med ekspertise, erfaring og den nyeste teknologien, sier Anna-Carin Standberg, CEO Livio Group." },
    { type: "paragraph", text: "Inntil videre vil CMedical og Livio Oslo fortsette som separate selskaper. Oppkjøpet vil ikke få praktisk betydning for pasientenes pågående behandlingsløp eller oppbevaring av fryste egg, sæd eller embryoer." },
    { type: "heading", text: "Unikt tilbud til fertilitetspasienter i Norge" },
    { type: "paragraph", text: "Tilbudet til pasientene blir styrket. CMedical er den første klinikken i Norden med fertilitetsbehandling og kirurgi – inkludert robotkirurgi – samlet på ett sted. Livio Oslo utfyller dagens tilbud med å kunne tilby sæd- og eggdonasjon fra norske donorer. I tillegg blir det totale tilbudet styrket i Oslo, for utredning og behandling av mannlig infertilitet. CMedical tilbyr fra før avansert behandling med Micro-TESE, som betyr uthenting av sædceller med mikrokirurgi." },
    { type: "quote", text: "– Stadig flere par har vansker med å unnfange barn uten hjelp og våre fertilitetstjenester er høyt etterspurt. Med Livio Oslos toppteam og lange erfaring blir vi enda bedre rustet for å løse de mange utfordringene ufrivillige barnløse møter. CMedical er et kompetansesenter for kvinnehelse med tverrfaglig tilnærming, sier Madeleine Engen, medgründer og fagansvarlig gynekolog i CMedical. Hos oss møter du engasjerte kirurger, gynekologer, urologer og fertilitetsleger som jobber med den sykdommen de kan best – i unike tverrfaglige team, bestående av osteopater, ernæringsfysiologer, sexologer, psykologer og fysioterapeuter. Sammen skreddersyr vi behandlingen som er best tilpasset pasienten. Vi har anledning til å følge pasienten før, under og etter en fertilitetsbehandling, uansett om det blir barn eller ikke. Vi er rustet til å ivareta pasienten psykisk og fysisk igjennom et helt livsløp, avslutter hun." },
    { type: "paragraph", text: "CMedical er Nordens ledende klinikk for kvinnen og mannens underliv med flere spesialistklinikker i Norge og Sverige. Selskapet har blant annet bygget opp egne fertilitetsklinikker i Stockholm, Uppsala og Oslo, og kjøper nå senest opp Livio i Oslo. Tidligere i år kjøpte CMedical opp den kjente kvinnehelsetjenesten HerCare i Sverige. CMedical har ellers store fagmiljøer på gynekologi, ortopedi og urologi. Les mer her: www.cmedical.no" },
    { type: "paragraph", text: "Spørsmål rettes til Gard Lauvsnes (CEO CMedical Group) på telefon 920 51 610, eller sendes skriftlig til gard@colosseum.no eller unni.lovise.berge@cmedical.no (CMO)." },
  ],

  "tanken-slo-meg-ikke-at-det-kunne-vaere-meg": [
    { type: "bold-intro", text: "Når barn uteblir, tror mange automatisk at problemet ligger hos kvinnen, men i én av tre tilfeller skyldes det faktisk mannen. Likevel nøler mange menn med å sjekke seg. Nå deler Synne Pernille Jakobsen og Chris Kristiansen sin historie for å bryte tabuet – og oppfordrer par til å sjekke seg tidlig." },
    { type: "paragraph", text: "Etter måneder uten graviditet var paret overbevist om at utfordringen lå hos Synne. Hun kjente på en sterk følelse av ansvar, frustrasjon og sorg. Da de dro til legen, var hun mentalt forberedt på å få en nedslående beskjed, men testene viste ingen problemer med livmoren eller eggkvaliteten hennes. Da måtte begge omstille seg." },
    { type: "quote", text: "– Jeg tenkte rett og slett ikke på at det kunne være meg, sier Chris." },
    { type: "paragraph", text: "Heller ikke Synne hadde tenkt tanken, noe som fikk henne til å reflektere over hvor raskt kvinner tar på seg ansvaret." },
    { type: "quote", text: "– Infertilitet kan ramme begge, og ingen er mer skyldig enn den andre. Likevel er det ofte kvinnen som forventes å “lykkes” med graviditeten, og som kjenner på ansvaret når det ikke går. Det kan være en stor belastning, sier hun." },
    { type: "paragraph", text: "For noen år siden hadde Chris tatt en fertilitetstest som viste god kvalitet. Men mye kan endre seg på kort tid, og det hadde endret seg nettopp denne gangen. Da svaret på hans tester kom, var resultatet helt uventet." },
    { type: "quote", text: "– Beskjeden var både vond og overraskende, og mitt første instinkt var å kontrollsjekke resultatet. Men det viste seg på nytt at kvaliteten var ikke god nok, og legen vår sa rett ut at naturlig graviditet ville bli svært vanskelig, forteller han." },
    { type: "heading", text: "Rammer én av 20 menn" },
    { type: "paragraph", text: "Rundt 15 prosent av alle par opplever utfordringer med å bli gravide, og i 30-40 prosent av tilfellene ligger årsaken hos mannen. Samtidig har sædkvaliteten sunket betydelig de siste tiårene, og i dag rammes omtrent én av 20 menn av mannlig infertilitet. Jackson Tok, fertilitetslege hos CMedical, forklarer at mange menn synes det er vanskelig å snakke om diagnosen sin." },
    { type: "quote", text: "– Frykten for å bli sett ned på eller føle seg mindre maskulin gjør at mange velger å tie. Det er nok mye av grunnen til at det snakkes så lite om, og at mange ikke engang vurderer at dette kan være årsaken til at de ikke blir gravide. Dermed vet de heller ikke hvilken hjelp som finnes, sier han." },
    { type: "paragraph", text: "Chris kjente på de samme tankene i starten, men åpenhet og god informasjon fra legen gjorde prosessen enklere. Samtidig har teknologien og behandlingen gitt ham et nytt perspektiv." },
    { type: "quote", text: "– Jeg innså at dette ikke var noe jeg burde skamme meg over, og at infertilitet ikke definerer meg. Vi har ikke mislyktes – vi bare trengte litt hjelp, sier han." },
    { type: "quote", text: "– Det som var et problem, ble ikke lenger et problem" },
    { type: "paragraph", text: "Heldigvis tok paret raskt grep og startet en assistert befruktningsprosess hos CMedical. Ettersom Synne har en muskelknute i livmoren, ble eggeuttaket gjort vaginalt på den ene siden og gjennom magen på den andre siden der muskelknuten sitter." },
    { type: "quote", text: "– Det var en intens og smertefull prosess, men når noe er så sterkt ønsket, blir smerte relativt. Vi fikk ut hele 23 egg, og så gjensto det bare å finne de beste svømmerne, sier hun." },
    { type: "quote", text: "– Det var sterkt å vite at vi hadde en sjanse, legger Chris til." },
    { type: "paragraph", text: "Med intracytoplasmatisk sædcelleinjeksjon (ICSI) ble paret gravide på første forsøk. I tillegg har de tre nedfryste embryoer, som kan bli mulige søsken i fremtiden." },
    { type: "quote", text: "– Etter innsettet kjente jeg umiddelbart at det var liv. Det var en helt ubeskrivelig følelse å endelig bli gravid, sier Synne og legger til:" },
    { type: "quote", text: "– Men å streve så lenge med å bli gravide satte sitt preg på oss, og selv med en positiv test slapp vi ikke unna frykten for at noe kunne gå galt. Heldigvis følte vi oss ekstra godt ivaretatt i første trimester og har fått utrolig god oppfølging både før, under og etter graviditeten. I dag er vi evig takknemlige for at vi har en nydelig datter, sier Synne." },
    { type: "paragraph", text: "Synne og Chris håper at deres historie kan bidra til å løfte tematikken rundt mannlig infertilitet og gjøre det lettere for andre å oppsøke hjelp. I dag er også Chris langt mer komfortabel med å være åpen om sin situasjon." },
    { type: "quote", text: "– Det som var et problem, ble ikke lenger et problem. Og jeg tror dessverre at det kan være mange menn der ute som sitter med den samme utfordringen, men ikke tør å snakke om det. Det er ingen skam i å få hjelp, og det må vi få satt på agendaen, avslutter han." },
    { type: "heading", text: "Om intracytoplasmatisk sædcelleinjeksjon" },
    { type: "paragraph", text: "ICSI er en avansert metode innen assistert befruktning som brukes når sædkvaliteten er redusert. I en vanlig IVF-prosess blandes sædceller med eggceller i en skål, og befruktningen skjer naturlig. Ved ICSI blir derimot én enkelt sædcelle direkte injisert inn i egget med en tynn mikropipette for å øke sjansene for befruktning." },
  ],

  "ved-a-lukke-kvinnehelsegapet-kan-hver-kvinne-fa-syv-flere-friske-dager-i-lopet-av-et-ar": [
    { type: "heading", text: "Økt fokus på kvinnehelse er ikke bare et politisk ansvar. Det er også økonomisk lønnsomt." },
    { type: "quote", text: "Dr. Madeleine Engen, gynekolog og medgründer CMedical Kvinnehelse" },
    { type: "paragraph", text: "Ved å lukke kvinnehelsegapet kan vi tilføre norsk økonomi 80 milliarder kroner innen 2040, rapporterer McKinsey og World Economic Forum1. Et forbedret helsetilbud til kvinner vil gi færre helseutfordringer og bedre livskvalitet, økt deltakelse i arbeidslivet og hevet produktivitet. Det er både politikerne, næringslivet og familielivet tjent med." },
    { type: "heading", text: "Kvinner er 25% mer syke enn menn" },
    { type: "paragraph", text: "Vi kan ikke snakke om sykefravær uten å snakke om kvinnehelse. Sammenlignet med menn tilbringer kvinner 25% mer av livet i dårlig helse. Dette helsegapet skyldes mangel på forskning og innovasjon, lang diagnostiseringstid og dårlig tilgang til effektiv behandling for kvinnesykdommer." },
    { type: "paragraph", text: "Kvinner i arbeidsfør alder bærer den største sykdomsbyrden. Etter kreft og hjerte- og karsykdommer er gynekologiske helseutfordringer den tredje største årsaken til kvinners tap av leveår i god helse. Overgangsalder, endometriose og PMS er blant de helsetilstandene som påvirker produktiviteten og deltakelsen i arbeidslivet mest." },
    { type: "heading", text: "Investeringer i kvinnehelse lønner seg" },
    { type: "paragraph", text: "McKinsey estimerer at for hver krone investert i forskning og behandling av kvinnehelseutfordringer forventes tre kroner i økonomisk vekst. Ved å lukke kvinnehelsegapet kan hver kvinne få syv flere friske dager i løpet av et år. Det kan ha en enorm påvirkning på offentlige helseutgifter og arbeidslivsdeltakelse." },
    { type: "heading", text: "Hvordan kan vi lukke kvinnehelsegapet?" },
    { type: "paragraph", text: "Det er særlig tre tiltak som kan bidra til å lukke kvinnehelsegapet. For det første er vi nødt til å gjøre et kunnskaps- og kompetanseløft om kvinnesykdommer i både befolkningen og helsevesenet." },
    { type: "paragraph", text: "Videre er vi nødt til å få ned helsekøene og gi kvinner tilgang på riktig og effektiv behandling. Skal vi lytte til befolkningen etterlyser fire av fem et tettere samarbeid mellom offentlig og privat helsetjeneste. Én av fire oppgir at de har brukt private helsetjenester det siste året på grunn av lang ventetid hos fastlegen." },
    { type: "heading", text: "Samarbeid nødvendig" },
    { type: "paragraph", text: "Det finnes allerede private helsetjenester som er spesialiserte på overgangsalder, endometriose og andre gynekologiske helseutfordringer. Vi har den kompetansen som etterlyses og kan være med på et kunnskapsløft og å avlaste det offentlige helsevesenet, gi reduserte helsekøer og et forbedret behandlingstilbud for kvinner." },
    { type: "paragraph", text: "La oss samarbeide om å lukke kvinnehelsegapet i Norge. Det er vi alle tjent med." },
  ],

};
